{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a structurally related methoxybenzamide anilide containing a piperidine, has an absolute oral bioavailability of 32 ± 7% in normal subjects and 20–30% in healthy subjects, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ketanserin, a fluorophenyl piperidine with moderate polarity, has an absolute oral bioavailability of about 50–55% in healthy subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Safinamide, a fluorobenzyl ether amide, has an absolute oral bioavailability of 95% in healthy volunteers, demonstrating that this chemotype can achieve very high oral exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Vernakalant, a methoxyphenyl piperidine ether, has an absolute oral bioavailability of 58 ± 19% to 71 ± 21% in healthy volunteers, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Haloperidol, a fluorophenyl/chlorophenyl piperidine, shows absolute oral bioavailability values of 35–70% across studies, all above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Ebastine, a piperidine with an ether-linked diaryl group, has about 40% oral bioavailability in humans, still clearly above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability at or above 20%, with most values between 30% and 95%. The consistent supportive evidence from structurally related piperidine/amide/ether-containing drugs outweighs the mixed physicochemical prior, so the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule.",
    "The primary aromatic amine and high rotatable-bond count could introduce first-pass metabolism or permeability liabilities not fully captured by the analogues.",
    "Exact human F for the query is unknown; prediction relies on extrapolation from close analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

